import {api,ready,escapeHtml as esc,tr,money,errorMessage,toast} from './app.js';
let data,tab='products';const target=document.querySelector('#admin-table'),status=document.querySelector('#admin-status');
async function load(){await ready;try{data=await api('admin');status.hidden=true;document.querySelector('#admin-content').hidden=false;render();}catch(e){status.textContent=errorMessage(e);status.hidden=false;document.querySelector('#admin-content').hidden=true;}}
function render(){if(tab==='products'){target.innerHTML=`<button class="btn primary" id="new-product">${tr('Tambah produk','Add product')}</button><table><thead><tr><th>Produk</th><th>Harga</th><th>Status</th><th></th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${esc(p.title)}</td><td>${money(p.price_idr)}</td><td>${p.active?'Active':'Draft'}</td><td><button class="btn" data-edit="${esc(p.id)}">Edit</button></td></tr>`).join('')}</tbody></table>`;target.querySelector('#new-product').onclick=()=>editProduct({id:'',title:'',price_idr:10000,active:false});target.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProduct(data.products.find(p=>p.id===b.dataset.edit)));}else if(tab==='customers'){target.innerHTML=`<table><thead><tr><th>Email</th><th>Nama</th><th>Status</th><th></th></tr></thead><tbody>${data.customers.map(c=>`<tr><td>${esc(c.email)}</td><td>${esc(c.display_name)}</td><td>${c.blocked?'Restricted':'Active'}</td><td><button class="btn" data-customer="${esc(c.id)}">Edit</button></td></tr>`).join('')}</tbody></table>`;target.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>editCustomer(data.customers.find(c=>c.id===b.dataset.customer)));}else{target.innerHTML=`<table><thead><tr><th>Order</th><th>Produk</th><th>Harga</th><th>Status</th><th></th></tr></thead><tbody>${data.orders.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.product_id)}</td><td>${money(o.amount_idr)}</td><td>${esc(o.status)}</td><td><button class="btn" data-sync="${esc(o.id)}">Sync Midtrans</button></td></tr>`).join('')}</tbody></table>`;target.querySelectorAll('[data-sync]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('admin',{action:'sync',orderId:b.dataset.sync});await load();}catch(e){toast(errorMessage(e));b.disabled=false;}});}}
const field=(name,label,value,type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['id','title','price_idr'].includes(name)?'required':''}></label>`;
function editor(html,submit){const d=document.querySelector('#edit-dialog'),c=document.querySelector('#edit-content');c.innerHTML=`<form>${html}<button class="btn primary">${tr('Simpan','Save')}</button><p role="status" class="error"></p></form>`;d.showModal();c.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{await submit(new FormData(e.currentTarget));d.close();await load();}catch(err){c.querySelector('.error').textContent=errorMessage(err);b.disabled=false;}};}
function editProduct(p){editor(field('id','Product ID',p.id)+field('title','Nama / Title',p.title)+field('category','Kategori / Category',p.category||'')+field('description','Deskripsi / Description',p.description||'')+field('price_idr','Harga IDR / Price IDR',p.price_idr,'number')+field('storage_path','File privat / Private file',p.storage_path||'')+`<label><span><input name="active" type="checkbox" ${p.active?'checked':''}> Aktif / Active</span></label>`,f=>api('admin',{action:'product',...Object.fromEntries(f),price_idr:Number(f.get('price_idr')),active:f.has('active')}));if(p.id)document.querySelector('[name=id]').readOnly=true;}
function editCustomer(c){editor(field('display_name','Nama / Name',c.display_name)+`<p>${esc(c.email)}</p><label><span><input name="blocked" type="checkbox" ${c.blocked?'checked':''}> Batasi akses / Restrict access</span></label>`,f=>api('admin',{action:'customer',id:c.id,display_name:f.get('display_name'),blocked:f.has('blocked')}));}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.querySelector('#refresh').onclick=load;load();
